/* Public, read-only market access. Paper trades remain in this browser. */
(()=>{
const API='https://api.hyperliquid.xyz/info',TF={'5m':300,'15m':900,'30m':1800,'1h':3600,'4h':14400,'1d':86400,'1w':604800};
const limits={leverage:40,max_margin:5,max_risk:1,daily_loss_limit:5,fee_bps:4.5,slippage_bps:2};
const storageKey='btc-atelier-web-paper-v1';
let storageOK=true;try{localStorage.setItem('btc-storage-check','1');localStorage.removeItem('btc-storage-check')}catch{storageOK=false}
const emptyPaper=()=>({initial:50,cash:50,position:null,history:[],day:'',dailyPnl:0});
let paper=emptyPaper();
function readPaper(){try{const p=JSON.parse(localStorage.getItem(storageKey));if(p&&Number.isFinite(p.cash)&&Array.isArray(p.history))paper=p}catch{}return paper}
readPaper();
const bars={},statuses={},indicators={};let book=null,lastEvent=0,context={},contextAt=0,bookRequestAt=0,trades=[],flowStart=Date.now(),socket,lastWS=0,reconnect,fetching=new Map(),seen=new Set(),account=null,accountTime=0,accountError='',address='',storageWarning=storageOK?'':'Stockage indisponible : simulation désactivée.';
function save(){if(!storageOK)throw Error('Stockage indisponible : simulation désactivée.');localStorage.setItem(storageKey,JSON.stringify(paper));}
async function info(body){const c=new AbortController(),timeout=setTimeout(()=>c.abort(),12000);try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal});if(!r.ok)throw Error('Hyperliquid : HTTP '+r.status);return await r.json()}finally{clearTimeout(timeout)}}
function ema(values,n){let e=values[0];return values.map((v,i)=>i?(e+=2/(n+1)*(v-e)):e)}
function features(raw,now=Date.now()){
 const b=raw.filter(x=>+x.T<now).sort((a,b)=>a.t-b.t);if(b.length<51)return {ready:false};
 const c=b.map(x=>+x.c),v=b.map(x=>+x.v),e20=ema(c,20),e50=ema(c,50),e200=ema(c,200),fast=ema(c,12),slow=ema(c,26),macd=fast.map((x,i)=>x-slow[i]),signal=ema(macd,9);
 let gain=0,loss=0,atr=0;for(let i=1;i<=14;i++){gain+=Math.max(0,c[i]-c[i-1])/14;loss+=Math.max(0,c[i-1]-c[i])/14;atr+=Math.max(+b[i].h-b[i].l,Math.abs(b[i].h-c[i-1]),Math.abs(b[i].l-c[i-1]))/14}
 for(let i=15;i<c.length;i++){gain=(gain*13+Math.max(0,c[i]-c[i-1]))/14;loss=(loss*13+Math.max(0,c[i-1]-c[i]))/14;atr=(atr*13+Math.max(+b[i].h-b[i].l,Math.abs(b[i].h-c[i-1]),Math.abs(b[i].l-c[i-1])))/14}
 const recent=b.slice(-40),sumV=recent.reduce((s,b)=>s+(+b.v),0),mean=c.slice(-20).reduce((s,x)=>s+x,0)/20,sd=Math.sqrt(c.slice(-20).reduce((s,x)=>s+(x-mean)**2,0)/20),last=c.at(-1),longTrendReady=b.length>=250;
 return {ready:true,backend:'JavaScript',close:last,ema20:e20.at(-1),ema50:e50.at(-1),ema200:longTrendReady?e200.at(-1):null,longTrendReady,rsi:!gain&&!loss?50:!loss?100:100-100/(1+gain/loss),atr,macd:macd.at(-1),histogram:macd.at(-1)-signal.at(-1),rollingVwap:sumV?recent.reduce((s,b)=>s+(+b.h + +b.l + +b.c)/3*(+b.v),0)/sumV:null,bbLower:mean-2*sd,bbUpper:mean+2*sd,relativeVolume:v.at(-1)/(v.slice(-21,-1).reduce((s,x)=>s+x,0)/20||1),adx:null,cmf:null,obvChange20:null,trend:last>e20.at(-1)&&e20.at(-1)>e50.at(-1)?'bullish':last<e20.at(-1)&&e20.at(-1)<e50.at(-1)?'bearish':'neutral',regime:'unavailable',candidates:[]};
}
async function candles(tf){if(fetching.has(tf))return fetching.get(tf);if(statuses[tf]&&Date.now()/1000-statuses[tf].fetchedAt<60)return;
 const task=info({type:'candleSnapshot',req:{coin:'BTC',interval:tf,startTime:Date.now()-TF[tf]*1000*350,endTime:Date.now()}}).then(result=>{if(!Array.isArray(result))throw Error('Historique invalide');bars[tf]=result.filter(b=>['o','h','l','c','v','t','T'].every(k=>Number.isFinite(+b[k]))).sort((a,b)=>a.t-b.t);statuses[tf]={fetchedAt:Date.now()/1000};indicators[tf]=features(bars[tf]);}).finally(()=>fetching.delete(tf));fetching.set(tf,task);return task;}
function market(){const now=Date.now()/1000,age=book?now-book.time/1000:Infinity,mid=book?(+book.levels[0][0].px + +book.levels[1][0].px)/2:null;return {book,mid,connected:!!book&&now-lastEvent<20,lastEvent,sourceAgeSeconds:Number.isFinite(age)?age:null,fresh:!!mid&&now-lastEvent<15&&Math.abs(age)<20};}
function receiveBook(data){if(!data?.levels?.[0]?.length||!data?.levels?.[1]?.length)return;book=data;lastEvent=Date.now()/1000;}
function connect(){if(document.hidden)return;clearTimeout(reconnect);if(socket&&[0,1].includes(socket.readyState))return;
 socket=new WebSocket('wss://api.hyperliquid.xyz/ws');socket.onopen=()=>{flowStart=Date.now();trades=[];seen.clear();for(const type of ['l2Book','trades'])socket.send(JSON.stringify({method:'subscribe',subscription:{type,coin:'BTC'}}));lastWS=Date.now()};
 socket.onmessage=event=>{lastWS=Date.now();try{const e=JSON.parse(event.data);if(e.channel==='l2Book')receiveBook(e.data);if(e.channel==='trades')for(const t of e.data){const id=t.tid+':'+t.time;if(seen.has(id))continue;seen.add(id);trades.push(t)}trades=trades.filter(t=>+t.time>Date.now()-60000);if(seen.size>20000)seen.clear()}catch{}};
 socket.onclose=()=>{trades=[];flowStart=Date.now();if(!document.hidden)reconnect=setTimeout(connect,5000)};socket.onerror=()=>socket.close();}
setInterval(()=>{if(socket?.readyState===1){if(Date.now()-lastWS>45000)socket.close();else socket.send(JSON.stringify({method:'ping'}))}},20000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){socket?.close();lastEvent=0}else connect()});connect();
async function refreshMarket(){if(!market().fresh&&Date.now()-bookRequestAt>5000){bookRequestAt=Date.now();try{receiveBook(await info({type:'l2Book',coin:'BTC'}))}catch{}}
 if(Date.now()-contextAt>60000){contextAt=Date.now();try{const result=await info({type:'metaAndAssetCtxs'});const i=result[0].universe.findIndex(x=>x.name==='BTC');context=result[1][i]||{}}catch{}}
}
function profiles(){const b=(bars['30m']||[]).filter(x=>+x.T<Date.now()).slice(-48);if(!b.length)return [];const low=Math.min(...b.map(x=>+x.l)),high=Math.max(...b.map(x=>+x.h)),width=Math.max((high-low)/32,1),out=Array.from({length:32},(_,i)=>({price:low+(i+.5)*width,volume:0,tpo:0}));for(const x of b){const start=Math.max(0,Math.min(31,Math.floor((x.l-low)/width))),end=Math.max(start,Math.min(31,Math.floor((x.h-low)/width)));for(let i=start;i<=end;i++){out[i].tpo++;out[i].volume+=x.v/(end-start+1)}}return out;}
function lock(fn){if(!navigator.locks)throw Error('Simulation indisponible sur ce navigateur : verrouillage de stockage non pris en charge.');return navigator.locks.request('btc-paper',()=>{readPaper();return fn()})}
function resetDay(){const day=new Date().toISOString().slice(0,10);if(paper.day!==day){paper.day=day;paper.dailyPnl=0}}
function execution(side,qty){const levels=book.levels[side==='buy'?1:0];let left=qty,total=0;for(const level of levels){const fill=Math.min(left,+level.sz);total+=fill*level.px;left-=fill;if(left<=1e-12)break}if(left>1e-12)throw Error('Profondeur insuffisante pour la simulation.');return total/qty*(1+(side==='buy'?1:-1)*limits.slippage_bps/10000)}
function close(reason){const p=paper.position;if(!p)throw Error('Aucune position.');if(!market().fresh||document.hidden)throw Error('Données anciennes : clôture indisponible.');const exit=execution(p.side==='long'?'sell':'buy',p.quantity),gross=(p.side==='long'?1:-1)*(exit-p.entry)*p.quantity,fee=exit*p.quantity*limits.fee_bps/10000,net=gross-fee-p.entryFee;resetDay();paper.cash+=gross-fee;paper.dailyPnl+=net;paper.history.push({reason,side:p.side,netPnl:net,entry:p.entry,exit,at:new Date().toISOString()});paper.position=null;save();}
async function manage(){if(!paper.position||!market().fresh||document.hidden||!navigator.locks)return;return lock(()=>{const p=paper.position;if(!p)return;const px=+book.levels[p.side==='long'?0:1][0].px,d=p.side==='long'?1:-1;if(d*(px-p.stop)<=0)close('Stop observé');else if(d*(px-p.target)>=0)close('Objectif observé')})}
async function snapshot(tf){await Promise.allSettled([refreshMarket(),candles(tf)]);readPaper();try{await manage()}catch{}
 const now=Date.now()/1000,m=market(),p=paper.position,unrealized=p&&m.mid?(p.side==='long'?1:-1)*(m.mid-p.entry)*p.quantity:0,flow=trades.filter(x=>x.time>Date.now()-60000),buy=flow.filter(x=>x.side==='B').reduce((s,x)=>s+(+x.sz),0),sell=flow.filter(x=>x.side==='A').reduce((s,x)=>s+(+x.sz),0);
 return {instanceId:'browser-v1',time:now,market:m,context,paper:{...paper,equity:paper.cash+unrealized,unrealized},limits,flow:{buyBtc:buy,sellBtc:sell,deltaBtc:buy-sell,count:flow.length,coverage:socket?.readyState===1&&Date.now()-flowStart>60000?'fenêtre observée 60 s':'fenêtre incomplète / reconnexion'},indicators,candlesByTimeframe:bars,candleStatus:statuses,profiles:profiles(),scenario:{context:'Lecture descriptive',reasons:[storageWarning||'Édition navigateur : données publiques Hyperliquid.', 'Indicateurs JavaScript sur bougies clôturées ; aucune entrée automatique.','Historique et surveillance liés à cet appareil.']},accountAddress:address||'Aucune adresse renseignée',account,accountTime,accountError,agentConnection:{},research:{ready:false},strategyResearch:{},multiTimeframe:{rows:Object.keys(TF).map(timeframe=>({timeframe,role:'Observation',...(indicators[timeframe]||{ready:false}),fresh:!!statuses[timeframe]&&now-statuses[timeframe].fetchedAt<120,candidates:[]})),active:[]}};
}
window.BrowserAtelier={async request(path,options={}){
 if(path.startsWith('/api/state'))return snapshot(new URL(path,location.href).searchParams.get('timeframe')||'5m');
 if(path==='/api/session')return {token:'browser-only'};
 if(path==='/api/agent-config')throw Error('MCP disponible uniquement dans la version Python locale.');
 if(path==='/api/paper/open')return lock(()=>{if(!storageOK)throw Error('Stockage indisponible.');const a=JSON.parse(options.body),m=market();resetDay();if(!m.fresh||document.hidden)throw Error('Flux indisponible ou ancien.');if(paper.position)throw Error('Une position est déjà ouverte.');if(!['long','short'].includes(a.side)||![a.margin,a.stop,a.target].every(Number.isFinite)||a.margin<=0||a.margin>5)throw Error('Paramètres de simulation invalides.');if(paper.dailyPnl<=-5)throw Error('Limite quotidienne atteinte.');const dir=a.side==='long'?1:-1,best=+book.levels[dir===1?1:0][0].px,quantity=a.margin*40/best,entry=execution(dir===1?'buy':'sell',quantity),entryFee=entry*quantity*.00045,risk=dir*(entry-a.stop)*quantity+entryFee+a.stop*quantity*.00065;if(dir*(entry-a.stop)<=0||dir*(a.target-entry)<=0||risk>1||paper.cash<a.margin+entryFee)throw Error('Stop, objectif, risque ou capital hors limites.');paper.cash-=entryFee;paper.position={side:a.side,leverage:40,quantity,entry,entryFee,stop:a.stop,target:a.target,margin:a.margin,liquidationEstimate:null};save();return {ok:true}});
 if(path==='/api/paper/close')return lock(()=>{close('Manuelle');return {ok:true}});
 throw Error('Fonction locale non disponible dans cette édition.');
},async setAddress(value){if(!/^0x[a-fA-F0-9]{40}$/.test(value))throw Error('Adresse publique invalide.');const result=await info({type:'clearinghouseState',user:value});address=value;account={perpetuals:result};accountTime=Date.now()/1000;accountError='';},features};
// Load the other horizons progressively; never fan out many requests at once.
(async()=>{for(const tf of Object.keys(TF)){try{await candles(tf)}catch{}await new Promise(r=>setTimeout(r,300))}})();
})();
